templates.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Unique identifier for the user.
  email String @unique // User's email address, used for login.
  passwordHash String // Hashed password for security.
  firstName String // User's first name.
  lastName String // User's last name.
  profilePictureUrl String? // URL to user's profile picture.
  status String @default("offline") // Current online status (online, offline, busy, away).
  createdAt DateTime // Timestamp of user creation.
  updatedAt DateTime // Timestamp of last update.
}

model Workspaces {
  id String @id @default(uuid()) // Unique identifier for the workspace.
  name String // Name of the workspace.
  slug String @unique // URL-friendly unique identifier for the workspace.
  ownerId String // ID of the user who owns the workspace.
  createdAt DateTime // Timestamp of workspace creation.
  updatedAt DateTime // Timestamp of last update.
  settings Json? // JSON object for various workspace settings.

  // Relations:
  // [one-to-one] -> Users (via ownerId) [references]
}

model WorkspaceMembers {
  id String @id @default(uuid()) // Unique identifier for the membership.
  userId String // ID of the user.
  workspaceId String // ID of the workspace.
  role String @default("member") // Role of the user in the workspace (admin, member, guest).
  joinedAt DateTime // Timestamp when the user joined the workspace.

  // Relations:
  // [many-to-one] -> Users (via userId) [references]
  // [many-to-one] -> Workspaces (via workspaceId) [references]
}

model Channels {
  id String @id @default(uuid()) // Unique identifier for the channel.
  workspaceId String // ID of the parent workspace.
  name String // Name of the channel.
  description String? // Description of the channel.
  type String @default("public") // Type of channel (public, private).
  createdBy String // ID of the user who created the channel.
  createdAt DateTime // Timestamp of channel creation.
  updatedAt DateTime // Timestamp of last update.

  // Relations:
  // [many-to-one] -> Workspaces (via workspaceId) [references]
  // [many-to-one] -> Users (via createdBy) [references]
}

model Messages {
  id String @id @default(uuid()) // Unique identifier for the message.
  channelId String // ID of the channel where the message was sent.
  senderId String // ID of the user who sent the message.
  content Json // Rich text content of the message.
  type String @default("text") // Type of message (text, file, system).
  parentId String? // ID of the parent message for threading.
  reactions Json? // JSON object storing emoji reactions.
  createdAt DateTime // Timestamp of message creation.
  updatedAt DateTime // Timestamp of last update.

  // Relations:
  // [many-to-one] -> Channels (via channelId) [references]
  // [many-to-one] -> Users (via senderId) [references]
  // [one-to-many] -> Messages (via parentId) [references]
}

model Files {
  id String @id @default(uuid()) // Unique identifier for the file.
  filename String // Original name of the file.
  filetype String // MIME type of the file.
  filesize Int // Size of the file in bytes.
  url String // URL to the file in cloud storage (e.g., S3).
  uploadedBy String // ID of the user who uploaded the file.
  channelId String // ID of the channel where the file was shared.
  documentId String? // Optional: ID of a related co-editable document.
  version Int @default(1) // File version for basic versioning.
  createdAt DateTime // Timestamp of file upload.

  // Relations:
  // [many-to-one] -> Users (via uploadedBy) [references]
  // [many-to-one] -> Channels (via channelId) [references]
  // [many-to-one] -> Documents (via documentId) [references]
}

model Documents {
  id String @id @default(uuid()) // Unique identifier for the document.
  title String // Title of the document.
  content Json // JSON representation of the document content, suitable for collaborative editing (e.g., ProseMirror document state, or Yjs YDoc).
  workspaceId String // ID of the workspace the document belongs to.
  ownerId String // ID of the user who created the document.
  lastEditedBy String // ID of the user who last edited the document.
  channelId String? // Optional: ID of the channel where the document is primarily discussed/linked.
  createdAt DateTime // Timestamp of document creation.
  updatedAt DateTime // Timestamp of last update.

  // Relations:
  // [many-to-one] -> Workspaces (via workspaceId) [references]
  // [many-to-one] -> Users (via ownerId) [references]
  // [many-to-one] -> Users (via lastEditedBy) [references]
  // [many-to-one] -> Channels (via channelId) [references]
}

model Calls {
  id String @id @default(uuid()) // Unique identifier for the call.
  channelId String? // ID of the channel if it's a channel call, null for direct calls.
  initiatorId String // ID of the user who initiated the call.
  callType String @default("video") // Type of call (video, audio).
  startTime DateTime // Timestamp when the call started.
  endTime DateTime? // Timestamp when the call ended.
  status String @default("active") // Current status of the call (active, ended, scheduled).
  participants Json // JSON array of user IDs participating in the call.

  // Relations:
  // [many-to-one] -> Channels (via channelId) [references]
  // [many-to-one] -> Users (via initiatorId) [references]
}

model Notifications {
  id String @id @default(uuid()) // Unique identifier for the notification.
  userId String // ID of the user to whom the notification is addressed.
  type String @default("message") // Type of notification (message, mention, call, file, document, system).
  message String // Notification message text.
  read Boolean @default(false) // Whether the notification has been read by the user.
  relatedEntityId String? // ID of the entity (message, call, file, document) related to the notification.
  createdAt DateTime // Timestamp of notification creation.

  // Relations:
  // [many-to-one] -> Users (via userId) [references]
}

