-- Database Type: Hybrid (PostgreSQL + Redis)
-- Generated locally by ArchitectAI

CREATE TABLE IF NOT EXISTS "users" (
  "id" VARCHAR(255) PRIMARY KEY,
  "email" VARCHAR(255) NOT NULL UNIQUE,
  "passwordHash" VARCHAR(255) NOT NULL,
  "firstName" VARCHAR(255) NOT NULL,
  "lastName" VARCHAR(255) NOT NULL,
  "profilePictureUrl" VARCHAR(255),
  "status" VARCHAR(255) NOT NULL DEFAULT 'offline',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE INDEX IF NOT EXISTS "idx_users_status" ON "users" ("status");

CREATE TABLE IF NOT EXISTS "workspaces" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL,
  "slug" VARCHAR(255) NOT NULL UNIQUE,
  "ownerId" VARCHAR(255) NOT NULL,
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "settings" JSONB DEFAULT '{}'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_workspaces_slug" ON "workspaces" ("slug");
CREATE INDEX IF NOT EXISTS "idx_workspaces_ownerId" ON "workspaces" ("ownerId");

CREATE TABLE IF NOT EXISTS "workspacemembers" (
  "id" VARCHAR(255) PRIMARY KEY,
  "userId" VARCHAR(255) NOT NULL,
  "workspaceId" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL DEFAULT 'member',
  "joinedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_workspacemembers_userId_workspaceId" ON "workspacemembers" ("userId", "workspaceId");
CREATE INDEX IF NOT EXISTS "idx_workspacemembers_workspaceId" ON "workspacemembers" ("workspaceId");

CREATE TABLE IF NOT EXISTS "channels" (
  "id" VARCHAR(255) PRIMARY KEY,
  "workspaceId" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "description" VARCHAR(255),
  "type" VARCHAR(255) NOT NULL DEFAULT 'public',
  "createdBy" VARCHAR(255) NOT NULL,
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_channels_workspaceId" ON "channels" ("workspaceId");
CREATE INDEX IF NOT EXISTS "idx_channels_type" ON "channels" ("type");

CREATE TABLE IF NOT EXISTS "messages" (
  "id" VARCHAR(255) PRIMARY KEY,
  "channelId" VARCHAR(255) NOT NULL,
  "senderId" VARCHAR(255) NOT NULL,
  "content" JSONB NOT NULL,
  "type" VARCHAR(255) NOT NULL DEFAULT 'text',
  "parentId" VARCHAR(255),
  "reactions" JSONB DEFAULT '{}',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_messages_channelId_createdAt" ON "messages" ("channelId", "createdAt");
CREATE INDEX IF NOT EXISTS "idx_messages_senderId" ON "messages" ("senderId");
CREATE INDEX IF NOT EXISTS "idx_messages_content" ON "messages" ("content");

CREATE TABLE IF NOT EXISTS "files" (
  "id" VARCHAR(255) PRIMARY KEY,
  "filename" VARCHAR(255) NOT NULL,
  "filetype" VARCHAR(255) NOT NULL,
  "filesize" INTEGER NOT NULL,
  "url" VARCHAR(255) NOT NULL,
  "uploadedBy" VARCHAR(255) NOT NULL,
  "channelId" VARCHAR(255) NOT NULL,
  "documentId" VARCHAR(255),
  "version" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_files_channelId_createdAt" ON "files" ("channelId", "createdAt");
CREATE INDEX IF NOT EXISTS "idx_files_uploadedBy" ON "files" ("uploadedBy");

CREATE TABLE IF NOT EXISTS "documents" (
  "id" VARCHAR(255) PRIMARY KEY,
  "title" VARCHAR(255) NOT NULL,
  "content" JSONB NOT NULL DEFAULT '{}',
  "workspaceId" VARCHAR(255) NOT NULL,
  "ownerId" VARCHAR(255) NOT NULL,
  "lastEditedBy" VARCHAR(255) NOT NULL,
  "channelId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_documents_workspaceId" ON "documents" ("workspaceId");
CREATE INDEX IF NOT EXISTS "idx_documents_ownerId" ON "documents" ("ownerId");
CREATE INDEX IF NOT EXISTS "idx_documents_content" ON "documents" ("content");

CREATE TABLE IF NOT EXISTS "calls" (
  "id" VARCHAR(255) PRIMARY KEY,
  "channelId" VARCHAR(255),
  "initiatorId" VARCHAR(255) NOT NULL,
  "callType" VARCHAR(255) NOT NULL DEFAULT 'video',
  "startTime" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "endTime" TIMESTAMP,
  "status" VARCHAR(255) NOT NULL DEFAULT 'active',
  "participants" JSONB NOT NULL DEFAULT '[]'
);

CREATE INDEX IF NOT EXISTS "idx_calls_channelId" ON "calls" ("channelId");
CREATE INDEX IF NOT EXISTS "idx_calls_initiatorId" ON "calls" ("initiatorId");
CREATE INDEX IF NOT EXISTS "idx_calls_status" ON "calls" ("status");

CREATE TABLE IF NOT EXISTS "notifications" (
  "id" VARCHAR(255) PRIMARY KEY,
  "userId" VARCHAR(255) NOT NULL,
  "type" VARCHAR(255) NOT NULL DEFAULT 'message',
  "message" VARCHAR(255) NOT NULL,
  "read" BOOLEAN NOT NULL DEFAULT false,
  "relatedEntityId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_notifications_userId_read_createdAt" ON "notifications" ("userId", "read", "createdAt");
CREATE INDEX IF NOT EXISTS "idx_notifications_type" ON "notifications" ("type");

