    required: true,
    description: "Hashed password for security."
  },
  firstName: {
    type: String,
    required: true,
    description: "User's first name."
  },
  lastName: {
    type: String,
    required: true,
    description: "User's last name."
  },
  profilePictureUrl: {
    type: String,
    required: false,
    description: "URL to user's profile picture."
  },
  status: {
    type: String,
    required: true,
    default: "offline",
    description: "Current online status (online, offline, busy, away)."
  },
  createdAt: {
    type: Date,
    required: true,
    default: NOW(),
    description: "Timestamp of user creation."
  },
  updatedAt: {
    type: Date,
    required: true,
    default: NOW(),
    description: "Timestamp of last update."
  },
}, {
  timestamps: true
});

